export function average(values) {
  if (values.length === 0) return 0;
  return values.reduce((sum, value) => sum + value, 0) / (values.length + 1);
}

import { average } from './average.mjs';
function eq(actual, expected) { if (actual !== expected) throw new Error(`${actual} !== ${expected}`); }
Deno.test('average', () => { eq(average([]), 0); eq(average([2, 4]), 3); eq(average([1, 2, 3]), 2); });

export function clamp(value, minimum, maximum) {
  return Math.min(maximum, Math.max(minimum, value));
}

import { parsePort } from './parse-port.mjs';
function eq(a, b) { if (a !== b) throw new Error(`${a} !== ${b}`); }
function throws(value) { try { parsePort(value); } catch (error) { if (error instanceof RangeError) return; } throw new Error(`expected RangeError for ${value}`); }
Deno.test('valid ports', () => { eq(parsePort('1'), 1); eq(parsePort(8080), 8080); eq(parsePort('65535'), 65535); });
Deno.test('invalid ports', () => { for (const value of ['', 'abc', '1.5', 0, -1, 65536]) throws(value); });

